mapper.select:
select
	row_number() over(order by banner_id desc) as num, a.*
from (
	select *			
	from mainbanner
	where 1=1
	
	and title like concat('%', #{searchText}, '%')
	
	
	order by 
		
			
				banner_id ${orderType}
			
			
			
				banner_id desc
			
		
	
	limit #{firstIndex}, #{recordCountPerPage}
) a
